/**
 * inkvec's own results for the transparent-image parity tests, printed by a harness that runs
 * inkvec 0.2.7's `native::extract_palette`, `native::label_image`, `native::trace_color` (stage
 * by stage up to the fades) and `native::fade::merge_fades` on the same single-precision images:
 * the random transparent cases and fade scenes of `native-scenes.ts`, and a few 128 px corpus
 * rasters stored as deflated straight RGBA bytes (base64) with their sources' licenses. Ink
 * values are single precision; models are inkvec's tokens (positions in inkvec's frame, pixel
 * centers at integers). Generated; do not edit by hand.
 */

/** A palette inkvec recovered, and the hash of its labels (`labelHash`). */
export interface NativePaletteRef {
  count: number
  inkLab: number[]
  inkRgb: number[]
  weight: number[]
  alpha: number[]
  labelHash: number
}

/** A fade inkvec minted: its label and both profiles as model tokens. */
export interface FadeTokens {
  label: number
  color: (string | number)[]
  alpha: (string | number)[]
}

/** A fill the fades stage wrote: its label, model tokens, chi² and parameter count. */
export interface FillTokens {
  label: number
  model: (string | number)[]
  chi2: number
  params: number
}

/** A corpus raster through the transparent-image front end, with the carve and fades inputs inkvec's later stages produced. */
export interface NativeCorpusRef {
  name: string
  license: string
  w: number
  h: number
  /** Straight RGBA bytes, deflated, base64. */
  rgba: string
  sigma0: number
  soft: boolean
  /** The palette and the hash of the first labels. */
  palette: NativePaletteRef
  /** The noise after the soft-intake raise. */
  sigma: number
  absorbed: number
  moved: number
  /** Labels after the first despeckle, and after the blend absorption. */
  l1Hash: number
  l2Hash: number
  /** inkvec's labels after its band merge and carve (deflated Int32, base64), and the inks before and after the naming of carved paint. */
  carve: { labels: string; from: number; inkBefore: number[]; inkAfter: number[] }
  /** The fades stage on those labels: the fills count and inks it was given, and what it returned. */
  fade: {
    nFills: number
    labelInk: number[]
    labelHash: number
    labelInkAfter: number[]
    nFades: number
    fades: FadeTokens[]
    /** Every fill it rewrote or added. */
    fills: FillTokens[]
    totalFills: number
  }
}

/** A fade scene of `native-scenes.ts` through the fades stage. */
export interface FadeSceneRef {
  name: string
  labelHash: number
  labelInk: number[]
  nFades: number
  fades: FadeTokens[]
  fills: FillTokens[]
}

